from google.cloud import logging_v2, translate_v3, bigquery_data_transfer_v1
from vertexai.preview.generative_models import GenerativeModel
import os

def get_logging_client():
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT environment variable not set.")
    return logging_v2.Client(project=project_id)

def get_generative_model(model_name="gemini-pro"):
    return GenerativeModel(model_name)

def get_translate_client():
    return translate_v3.TranslationServiceClient()

from typing import Dict, Any, List
from datetime import datetime

class LogEntry:
    def __init__(self, message: str, severity: str, timestamp: datetime, labels: Dict[str, str] = None, json_payload: Dict[str, Any] = None):
        self.message = message
        self.severity = severity
        self.timestamp = timestamp
        self.labels = labels if labels is not None else {}
        self.json_payload = json_payload if json_payload is not None else {}

    def to_dict(self):
        entry = {
            "message": self.message,
            "severity": self.severity,
            "timestamp": self.timestamp.isoformat(),
        }
        if self.labels:
            entry["labels"] = self.labels
        if self.json_payload:
            entry["json_payload"] = self.json_payload
        return entry


class LogQueryRequest:
    def __init__(self, query_string: str, time_range_seconds: int = 3600, page_size: int = 100):
        self.query_string = query_string
        self.time_range_seconds = time_range_seconds
        self.page_size = page_size


class LogQueryResponse:
    def __init__(self, entries: List[LogEntry], next_page_token: str = None):
        self.entries = entries
        self.next_page_token = next_page_token

from observability_client import get_generative_model
from typing import List, Dict, Any

def log_text_safety(log_messages: List[str]) -> Dict[str, Any]:
    model = get_generative_model("gemini-pro") # Using gemini-pro for safety checks

    safety_findings = {}
    for i, message in enumerate(log_messages):
        prompt = (
            "Analyze the following log message for any unsafe content, "
            "such as personally identifiable information (PII), sensitive data, "
            "or potentially harmful instructions. Respond with 'SAFE' if no unsafe content is found, "
            "otherwise describe the unsafe content. Only respond with SAFE or the description."
            f"\n\nLog Message: {message}"
        )
        response = model.generate_content(prompt)
        safety_findings[f"log_message_{i}"] = {"message": message, "safety_check": response.text.strip()}

    return safety_findings

from observability_client import get_translate_client
from typing import List, Dict

def log_message_translate(log_messages: List[str], target_language_code: str, project_id: str) -> Dict[str, str]:
    client = get_translate_client()

    parent = f"projects/{project_id}/locations/global"
\    translated_messages = {}
    for i, message in enumerate(log_messages):
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [message],
                "target_language_code": target_language_code,
            }
        )
        for translation in response.translations:
            translated_messages[f"log_message_{i}"] = translation.translated_text
            break # Only take the first translation

    return translated_messages
